        "file_path": "/private/tmp/rp1-evals/fc305311/workspace/src/yaml-validator/validator.ts",
        "content": "/**\n * Core YAML validation logic using Bun's built-in YAML parser.\n */\n\nimport type { ValidationResult, YAMLError, FileError } from \"./types\";\n\n/**\n * Validate YAML syntax for a single file.\n *\n * @param filePath - Absolute or relative path to YAML file\n * @returns ValidationResult indicating success or type of failure\n */\nexport async function validateFile(filePath: string): Promise<ValidationResult> {\n  let content: string;\n\n  try {\n    const file = Bun.file(filePath);\n    content = await file.text();\n  } catch (err) {\n    const error = err as NodeJS.ErrnoException;\n    const fileError: FileError = {\n      code: error.code ?? \"UNKNOWN\",\n      message: getFileErrorMessage(error),\n    };\n    return { status: \"file_error\", filePath, error: fileError };\n  }\n\n  try {\n    Bun.YAML.parse(content);\n    return { status: \"success\", filePath };\n  } catch (err) {\n    const error = err as SyntaxError & { line?: number; column?: number };\n    const yamlError: YAMLError = {\n      message: error.message,\n      line: error.line,\n      column: error.column,\n    };\n    return { status: \"validation_error\", filePath, error: yamlError };\n  }\n}\n\n/**\n * Validate multiple YAML files.\n *\n * @param filePaths - Array of file paths to validate\n * @returns Array of ValidationResult for each file\n */\nexport async function validateFiles(\n  filePaths: string[]\n): Promise<ValidationResult[]> {\n  const results: ValidationResult[] = [];\n\n  for (const filePath of filePaths) {\n    const result = await validateFile(filePath);\n    results.push(result);\n  }\n\n  return results;\n}\n\n/**\n * Convert file system error to human-readable message.\n */\nfunction getFileErrorMessage(error: NodeJS.ErrnoException): string {\n  switch (error.code) {\n    case \"ENOENT\":\n      return \"File not found\";\n    case \"EACCES\":\n      return \"Permission denied\";\n    case \"EISDIR\":\n      return \"Path is a directory, not a file\";\n    default:\n      return error.message;\n  }\n}\n"
