        "file_path": "/private/tmp/rp1-evals/fc305311/workspace/src/yaml-validator/validator.test.ts",
        "content": "import { describe, expect, test, beforeAll, afterAll } from \"bun:test\";\nimport { validateFile, validateFiles } from \"./validator\";\nimport {\n  formatSuccess,\n  formatValidationError,\n  formatFileError,\n  formatSummary,\n} from \"./formatter\";\nimport { join } from \"path\";\nimport { mkdtemp, rm, writeFile, mkdir } from \"fs/promises\";\nimport { tmpdir } from \"os\";\n\nlet testDir: string;\n\nbeforeAll(async () => {\n  testDir = await mkdtemp(join(tmpdir(), \"yaml-validator-test-\"));\n});\n\nafterAll(async () => {\n  await rm(testDir, { recursive: true });\n});\n\ndescribe(\"validateFile\", () => {\n  test(\"returns success for valid YAML\", async () => {\n    const filePath = join(testDir, \"valid.yaml\");\n    await writeFile(filePath, \"name: test\\nversion: 1.0.0\\n\");\n\n    const result = await validateFile(filePath);\n\n    expect(result.status).toBe(\"success\");\n    expect(result.filePath).toBe(filePath);\n  });\n\n  test(\"returns success for empty YAML file\", async () => {\n    const filePath = join(testDir, \"empty.yaml\");\n    await writeFile(filePath, \"\");\n\n    const result = await validateFile(filePath);\n\n    expect(result.status).toBe(\"success\");\n    expect(result.filePath).toBe(filePath);\n  });\n\n  test(\"returns success for YAML with only comments\", async () => {\n    const filePath = join(testDir, \"comments.yaml\");\n    await writeFile(filePath, \"# This is a comment\\n# Another comment\\n\");\n\n    const result = await validateFile(filePath);\n\n    expect(result.status).toBe(\"success\");\n    expect(result.filePath).toBe(filePath);\n  });\n\n  test(\"returns validation_error for invalid YAML syntax\", async () => {\n    const filePath = join(testDir, \"invalid.yaml\");\n    await writeFile(filePath, \"name: test\\n  bad_indent: value\\n\");\n\n    const result = await validateFile(filePath);\n\n    expect(result.status).toBe(\"validation_error\");\n    expect(result.filePath).toBe(filePath);\n    if (result.status === \"validation_error\") {\n      expect(result.error.message).toBeDefined();\n    }\n  });\n\n  test(\"includes line number in validation error when available\", async () => {\n    const filePath = join(testDir, \"invalid-line.yaml\");\n    await writeFile(filePath, \"valid: true\\n  invalid: indentation\\n\");\n\n    const result = await validateFile(filePath);\n\n    expect(result.status).toBe(\"validation_error\");\n    if (result.status === \"validation_error\") {\n      expect(typeof result.error.line).toBe(\"number\");\n    }\n  });\n\n  test(\"returns file_error with ENOENT for non-existent file\", async () => {\n    const filePath = join(testDir, \"does-not-exist.yaml\");\n\n    const result = await validateFile(filePath);\n\n    expect(result.status).toBe(\"file_error\");\n    expect(result.filePath).toBe(filePath);\n    if (result.status === \"file_error\") {\n      expect(result.error.code).toBe(\"ENOENT\");\n      expect(result.error.message).toBe(\"File not found\");\n    }\n  });\n\n  test(\"returns file_error for directory path\", async () => {\n    const dirPath = join(testDir, \"subdir\");\n    await mkdir(dirPath, { recursive: true });\n\n    const result = await validateFile(dirPath);\n\n    expect(result.status).toBe(\"file_error\");\n    expect(result.filePath).toBe(dirPath);\n    if (result.status === \"file_error\") {\n      expect(result.error.code).toBe(\"EISDIR\");\n    }\n  });\n});\n\ndescribe(\"validateFiles\", () => {\n  test(\"processes all files even when some fail\", async () => {\n    const validPath = join(testDir, \"multi-valid.yaml\");\n    const invalidPath = join(testDir, \"multi-invalid.yaml\");\n    const missingPath = join(testDir, \"multi-missing.yaml\");\n\n    await writeFile(validPath, \"key: value\\n\");\n    await writeFile(invalidPath, \"bad:\\n  indent: wrong\\n  another:\\n bad\\n\");\n\n    const results = await validateFiles([validPath, invalidPath, missingPath]);\n\n    expect(results).toHaveLength(3);\n    expect(results[0].status).toBe(\"success\");\n    expect(results[1].status).toBe(\"validation_error\");\n    expect(results[2].status).toBe(\"file_error\");\n  });\n\n  test(\"returns empty array for empty input\", async () => {\n    const results = await validateFiles([]);\n\n    expect(results).toHaveLength(0);\n  });\n\n  test(\"processes single file correctly\", async () => {\n    const filePath = join(testDir, \"single.yaml\");\n    await writeFile(filePath, \"single: file\\n\");\n\n    const results = await validateFiles([filePath]);\n\n    expect(results).toHaveLength(1);\n    expect(results[0].status).toBe(\"success\");\n  });\n});\n\ndescribe(\"formatSuccess\", () => {\n  test(\"produces expected output format\", () => {\n    const result = formatSuccess(\"config.yaml\");\n\n    expect(result).toBe(\"config.yaml: valid\");\n  });\n\n  test(\"handles paths with directories\", () => {\n    const result = formatSuccess(\"/path/to/config.yaml\");\n\n    expect(result).toBe(\"/path/to/config.yaml: valid\");\n  });\n});\n\ndescribe(\"formatValidationError\", () => {\n  test(\"includes line number when present\", () => {\n    const error = { message: \"bad indentation\", line: 42 };\n\n    const result = formatValidationError(\"config.yaml\", error);\n\n    expect(result).toBe(\"config.yaml (line 42): bad indentation\");\n  });\n\n  test(\"omits line number when not present\", () => {\n    const error = { message: \"invalid syntax\" };\n\n    const result = formatValidationError(\"config.yaml\", error);\n\n    expect(result).toBe(\"config.yaml: invalid syntax\");\n  });\n\n  test(\"handles line number with column\", () => {\n    const error = { message: \"unexpected token\", line: 10, column: 5 };\n\n    const result = formatValidationError(\"config.yaml\", error);\n\n    expect(result).toBe(\"config.yaml (line 10): unexpected token\");\n  });\n});\n\ndescribe(\"formatFileError\", () => {\n  test(\"produces expected output format\", () => {\n    const error = { code: \"ENOENT\", message: \"File not found\" };\n\n    const result = formatFileError(\"missing.yaml\", error);\n\n    expect(result).toBe(\"missing.yaml: File not found\");\n  });\n\n  test(\"handles permission denied error\", () => {\n    const error = { code: \"EACCES\", message: \"Permission denied\" };\n\n    const result = formatFileError(\"protected.yaml\", error);\n\n    expect(result).toBe(\"protected.yaml: Permission denied\");\n  });\n});\n\ndescribe(\"formatSummary\", () => {\n  test(\"produces expected output format\", () => {\n    const summary = { total: 5, passed: 3, failed: 1, fileErrors: 1 };\n\n    const result = formatSummary(summary);\n\n    expect(result).toBe(\n      \"Validated 5 files: 3 passed, 1 failed, 1 file errors\"\n    );\n  });\n\n  test(\"handles all passed\", () => {\n    const summary = { total: 3, passed: 3, failed: 0, fileErrors: 0 };\n\n    const result = formatSummary(summary);\n\n    expect(result).toBe(\n      \"Validated 3 files: 3 passed, 0 failed, 0 file errors\"\n    );\n  });\n\n  test(\"handles all failed\", () => {\n    const summary = { total: 2, passed: 0, failed: 2, fileErrors: 0 };\n\n    const result = formatSummary(summary);\n\n    expect(result).toBe(\n      \"Validated 2 files: 0 passed, 2 failed, 0 file errors\"\n    );\n  });\n});\n"
