/**
 * Output formatting utilities for the YAML validator command.
 */

import type { YAMLError, FileError, ValidationSummary } from "./types";

/**
 * Format a success message for stdout.
 *
 * @param filePath - Path to the validated file
 * @returns Formatted success message
 */
export function formatSuccess(filePath: string): string {
  return `${filePath}: valid`;
}

/**
 * Format a validation error message for stderr.
 *
 * @param filePath - Path to the invalid file
 * @param error - YAML parsing error details
 * @returns Formatted error message
 */
export function formatValidationError(filePath: string, error: YAMLError): string {
  const location = error.line ? ` (line ${error.line})` : "";
  return `${filePath}${location}: ${error.message}`;
}

/**
 * Format a file access error message for stderr.
 *
 * @param filePath - Path that could not be accessed
 * @param error - File system error details
 * @returns Formatted error message
 */
export function formatFileError(filePath: string, error: FileError): string {
  return `${filePath}: ${error.message}`;
}

/**
 * Format aggregate summary for stderr.
 *
 * @param summary - Aggregated validation results
 * @returns Formatted summary message
 */
export function formatSummary(summary: ValidationSummary): string {
  return `Validated ${summary.total} files: ${summary.passed} passed, ${summary.failed} failed, ${summary.fileErrors} file errors`;
}

/**
 * CLI entry point for the YAML validator command.
 */

import { validateFiles } from "./validator";
import {
  formatSuccess,
  formatValidationError,
  formatFileError,
  formatSummary,
} from "./formatter";
import { ExitCode, type ValidationResult, type ValidationSummary } from "./types";

/**
 * Calculate summary statistics from validation results.
 */
function calculateSummary(results: ValidationResult[]): ValidationSummary {
  let passed = 0;
  let failed = 0;
  let fileErrors = 0;

  for (const result of results) {
    switch (result.status) {
      case "success":
        passed++;
        break;
      case "validation_error":
        failed++;
        break;
      case "file_error":
        fileErrors++;
        break;
    }
  }

  return {
    total: results.length,
    passed,
    failed,
    fileErrors,
  };
}

async function main(): Promise<never> {
  const filePaths = process.argv.slice(2);

  if (filePaths.length === 0) {
    console.error("Usage: bun run validate <file1.yaml> [file2.yaml] ...");
    process.exit(ExitCode.FILE_ERROR);
  }

  const results = await validateFiles(filePaths);

  let hasFileError = false;
  let hasValidationError = false;

  for (const result of results) {
    switch (result.status) {
      case "success":
        console.log(formatSuccess(result.filePath));
        break;
      case "validation_error":
        console.error(formatValidationError(result.filePath, result.error));
        hasValidationError = true;
        break;
      case "file_error":
        console.error(formatFileError(result.filePath, result.error));
        hasFileError = true;
        break;
    }
  }

  if (results.length > 1) {
    const summary = calculateSummary(results);
    console.error(formatSummary(summary));
  }

  if (hasFileError) {
    process.exit(ExitCode.FILE_ERROR);
  } else if (hasValidationError) {
    process.exit(ExitCode.VALIDATION_ERROR);
  } else {
    process.exit(ExitCode.SUCCESS);
  }
}

main();

