        "file_path": "/private/tmp/rp1-evals/3d6f337b/workspace/.rp1/work/worktrees/feature-yaml-validator-command/src/yaml-validator.ts",
        "content": "/**\n * YAML Validator - Core validation logic for YAML syntax checking.\n * Implements pure TypeScript validation without external dependencies.\n */\n\n/**\n * Represents a single validation error with location and description.\n */\nexport interface ValidationError {\n  line: number;\n  column?: number;\n  message: string;\n}\n\n/**\n * Result of YAML validation containing validity status and any errors found.\n */\nexport interface ValidationResult {\n  valid: boolean;\n  errors: ValidationError[];\n}\n\n/**\n * Check for tab characters in YAML content.\n * YAML specification requires spaces for indentation.\n */\nexport function checkIndentation(lines: string[]): ValidationError[] {\n  const errors: ValidationError[] = [];\n  const indentStack: number[] = [0];\n\n  for (let i = 0; i < lines.length; i++) {\n    const line = lines[i];\n    const lineNum = i + 1;\n\n    // Skip empty lines and comments\n    if (line.trim() === \"\" || line.trim().startsWith(\"#\")) {\n      continue;\n    }\n\n    // Check for tab characters\n    const tabIndex = line.indexOf(\"\\t\");\n    if (tabIndex !== -1) {\n      errors.push({\n        line: lineNum,\n        column: tabIndex + 1,\n        message: \"Tab character found; use spaces for indentation\",\n      });\n      continue;\n    }\n\n    // Calculate current indentation\n    const match = line.match(/^( *)/);\n    const currentIndent = match ? match[1].length : 0;\n\n    // Skip lines that start with - (list items can have flexible indentation)\n    const trimmed = line.trim();\n    if (trimmed.startsWith(\"-\")) {\n      // Update indent stack for list items\n      while (indentStack.length > 1 && currentIndent < indentStack[indentStack.length - 1]) {\n        indentStack.pop();\n      }\n      if (currentIndent > indentStack[indentStack.length - 1]) {\n        indentStack.push(currentIndent);\n      }\n      continue;\n    }\n\n    // Check indentation consistency\n    const lastIndent = indentStack[indentStack.length - 1];\n\n    if (currentIndent > lastIndent) {\n      // New indentation level\n      indentStack.push(currentIndent);\n    } else if (currentIndent < lastIndent) {\n      // Dedent - must match a previous level\n      while (indentStack.length > 1 && currentIndent < indentStack[indentStack.length - 1]) {\n        indentStack.pop();\n      }\n      if (currentIndent !== indentStack[indentStack.length - 1]) {\n        errors.push({\n          line: lineNum,\n          column: 1,\n          message: \"Inconsistent indentation\",\n        });\n      }\n    }\n  }\n\n  return errors;\n}\n\n/**\n * Check for unclosed quotes (single and double).\n */\nexport function checkQuotes(lines: string[]): ValidationError[] {\n  const errors: ValidationError[] = [];\n\n  for (let i = 0; i < lines.length; i++) {\n    const line = lines[i];\n    const lineNum = i + 1;\n\n    // Skip comments\n    if (line.trim().startsWith(\"#\")) {\n      continue;\n    }\n\n    // Track quote state\n    let inSingleQuote = false;\n    let inDoubleQuote = false;\n    let escaped = false;\n\n    for (let j = 0; j < line.length; j++) {\n      const char = line[j];\n\n      if (escaped) {\n        escaped = false;\n        continue;\n      }\n\n      if (char === \"\\\\\") {\n        escaped = true;\n        continue;\n      }\n\n      if (char === \"'\" && !inDoubleQuote) {\n        inSingleQuote = !inSingleQuote;\n      } else if (char === '\"' && !inSingleQuote) {\n        inDoubleQuote = !inDoubleQuote;\n      }\n    }\n\n    if (inSingleQuote) {\n      errors.push({\n        line: lineNum,\n        message: \"Unclosed single quote\",\n      });\n    }\n\n    if (inDoubleQuote) {\n      errors.push({\n        line: lineNum,\n        message: \"Unclosed double quote\",\n      });\n    }\n  }\n\n  return errors;\n}\n\n/**\n * Check for unclosed brackets [] and braces {}.\n */\nexport function checkBrackets(lines: string[]): ValidationError[] {\n  const errors: ValidationError[] = [];\n  const stack: { char: string; line: number; column: number }[] = [];\n\n  for (let i = 0; i < lines.length; i++) {\n    const line = lines[i];\n    const lineNum = i + 1;\n\n    // Skip comments\n    if (line.trim().startsWith(\"#\")) {\n      continue;\n    }\n\n    // Track quote state to ignore brackets inside strings\n    let inSingleQuote = false;\n    let inDoubleQuote = false;\n    let escaped = false;\n\n    for (let j = 0; j < line.length; j++) {\n      const char = line[j];\n\n      if (escaped) {\n        escaped = false;\n        continue;\n      }\n\n      if (char === \"\\\\\") {\n        escaped = true;\n        continue;\n      }\n\n      if (char === \"'\" && !inDoubleQuote) {\n        inSingleQuote = !inSingleQuote;\n        continue;\n      }\n\n      if (char === '\"' && !inSingleQuote) {\n        inDoubleQuote = !inDoubleQuote;\n        continue;\n      }\n\n      // Only process brackets outside of quotes\n      if (!inSingleQuote && !inDoubleQuote) {\n        if (char === \"[\" || char === \"{\") {\n          stack.push({ char, line: lineNum, column: j + 1 });\n        } else if (char === \"]\" || char === \"}\") {\n          const expected = char === \"]\" ? \"[\" : \"{\";\n          if (stack.length === 0) {\n            errors.push({\n              line: lineNum,\n              column: j + 1,\n              message: `Unexpected closing '${char}'`,\n            });\n          } else if (stack[stack.length - 1].char !== expected) {\n            const last = stack[stack.length - 1];\n            errors.push({\n              line: lineNum,\n              column: j + 1,\n              message: `Mismatched bracket: expected '${last.char === \"[\" ? \"]\" : \"}\"}' but found '${char}'`,\n            });\n          } else {\n            stack.pop();\n          }\n        }\n      }\n    }\n  }\n\n  // Report unclosed brackets\n  for (const unclosed of stack) {\n    errors.push({\n      line: unclosed.line,\n      column: unclosed.column,\n      message: `Unclosed '${unclosed.char}'`,\n    });\n  }\n\n  return errors;\n}\n\n/**\n * Check for valid key-value syntax (colon followed by space or newline).\n */\nexport function checkKeyValueSyntax(lines: string[]): ValidationError[] {\n  const errors: ValidationError[] = [];\n\n  for (let i = 0; i < lines.length; i++) {\n    const line = lines[i];\n    const lineNum = i + 1;\n    const trimmed = line.trim();\n\n    // Skip empty lines, comments, list items without key-value, and document separators\n    if (\n      trimmed === \"\" ||\n      trimmed.startsWith(\"#\") ||\n      trimmed === \"---\" ||\n      trimmed === \"...\"\n    ) {\n      continue;\n    }\n\n    // Skip pure list items (just - value)\n    if (trimmed.match(/^-\\s*[^:]*$/)) {\n      continue;\n    }\n\n    // Skip flow sequences and mappings on their own\n    if (trimmed.startsWith(\"[\") || trimmed.startsWith(\"{\")) {\n      continue;\n    }\n\n    // Track quote state to find colons outside quotes\n    let inSingleQuote = false;\n    let inDoubleQuote = false;\n    let escaped = false;\n    let colonIndex = -1;\n\n    for (let j = 0; j < line.length; j++) {\n      const char = line[j];\n\n      if (escaped) {\n        escaped = false;\n        continue;\n      }\n\n      if (char === \"\\\\\") {\n        escaped = true;\n        continue;\n      }\n\n      if (char === \"'\" && !inDoubleQuote) {\n        inSingleQuote = !inSingleQuote;\n        continue;\n      }\n\n      if (char === '\"' && !inSingleQuote) {\n        inDoubleQuote = !inDoubleQuote;\n        continue;\n      }\n\n      if (char === \":\" && !inSingleQuote && !inDoubleQuote) {\n        colonIndex = j;\n        break;\n      }\n    }\n\n    // If we found a colon outside quotes, check what follows\n    if (colonIndex !== -1) {\n      const afterColon = line.substring(colonIndex + 1);\n      // Colon must be followed by space, newline (empty string), or nothing (end of line)\n      // Also allow if the value is a flow sequence/mapping\n      if (afterColon.length > 0 && afterColon[0] !== \" \" && afterColon[0] !== \"\\t\") {\n        // Check if it's followed by a flow indicator\n        if (afterColon[0] !== \"[\" && afterColon[0] !== \"{\") {\n          errors.push({\n            line: lineNum,\n            column: colonIndex + 2,\n            message: \"Invalid key-value syntax: colon must be followed by space\",\n          });\n        }\n      }\n    }\n  }\n\n  return errors;\n}\n\n/**\n * Check for valid multi-document separators (---) and document end markers (...).\n */\nexport function checkMultiDocument(lines: string[]): ValidationError[] {\n  const errors: ValidationError[] = [];\n\n  for (let i = 0; i < lines.length; i++) {\n    const line = lines[i];\n    const lineNum = i + 1;\n    const trimmed = line.trim();\n\n    // Check for malformed document separators\n    if (trimmed.startsWith(\"---\") && trimmed !== \"---\") {\n      // Allow --- followed by space and directive/tag\n      if (!trimmed.match(/^---\\s/)) {\n        errors.push({\n          line: lineNum,\n          message: \"Invalid document separator: must be exactly '---' or followed by space\",\n        });\n      }\n    }\n\n    // Check for malformed document end markers\n    if (trimmed.startsWith(\"...\") && trimmed !== \"...\") {\n      errors.push({\n        line: lineNum,\n        message: \"Invalid document end marker: must be exactly '...'\",\n      });\n    }\n  }\n\n  return errors;\n}\n\n/**\n * Main validation entry point.\n * Validates YAML content and returns a result with any errors found.\n */\nexport function validateYaml(content: string): ValidationResult {\n  // BR-002: Empty content is valid\n  if (content.trim() === \"\") {\n    return { valid: true, errors: [] };\n  }\n\n  const lines = content.split(\"\\n\");\n\n  // BR-003: Check if content is comments-only\n  const hasNonCommentContent = lines.some((line) => {\n    const trimmed = line.trim();\n    return trimmed !== \"\" && !trimmed.startsWith(\"#\");\n  });\n\n  if (!hasNonCommentContent) {\n    return { valid: true, errors: [] };\n  }\n\n  // Run all validation checks\n  const errors: ValidationError[] = [\n    ...checkIndentation(lines),\n    ...checkQuotes(lines),\n    ...checkBrackets(lines),\n    ...checkKeyValueSyntax(lines),\n    ...checkMultiDocument(lines),\n  ];\n\n  // Sort errors by line number\n  errors.sort((a, b) => a.line - b.line || (a.column ?? 0) - (b.column ?? 0));\n\n  return {\n    valid: errors.length === 0,\n    errors,\n  };\n}\n"
      },
