/**
 * CLI entry point for YAML validation.
 * Supports file path arguments and stdin input.
 */

import { validateYaml } from "./yaml-validator";

const HELP_TEXT = `Usage: bun run src/yaml-validate.ts [options] [file]

Arguments:
  file          Path to YAML file to validate

Options:
  -h, --help    Show this help message

Examples:
  bun run src/yaml-validate.ts config.yaml
  cat config.yaml | bun run src/yaml-validate.ts
  echo "key: value" | bun run src/yaml-validate.ts
`;

const EXIT_CODES = {
  VALID: 0,
  INVALID: 1,
  FILE_NOT_FOUND: 2,
  READ_ERROR: 3,
} as const;

async function main(): Promise<void> {
  const args = process.argv.slice(2);

  if (args.includes("-h") || args.includes("--help")) {
    console.log(HELP_TEXT);
    process.exit(EXIT_CODES.VALID);
  }

  const filePath = args.find((arg) => !arg.startsWith("-"));
  let content: string;

  if (filePath) {
    const file = Bun.file(filePath);
    const exists = await file.exists();

    if (!exists) {
      console.error(`File not found: ${filePath}`);
      process.exit(EXIT_CODES.FILE_NOT_FOUND);
    }

    try {
      content = await file.text();
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      console.error(`Read error: ${message}`);
      process.exit(EXIT_CODES.READ_ERROR);
    }
  } else {
    try {
      content = await Bun.stdin.text();
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      console.error(`Read error: ${message}`);
      process.exit(EXIT_CODES.READ_ERROR);
    }
  }

  const result = validateYaml(content);

  if (result.valid) {
    console.log("Valid YAML");
    process.exit(EXIT_CODES.VALID);
  }

  console.error("Invalid YAML:");
  for (const error of result.errors) {
    const location = error.column
      ? `Line ${error.line}, column ${error.column}`
      : `Line ${error.line}`;
    console.error(`  ${location}: ${error.message}`);
  }
  process.exit(EXIT_CODES.INVALID);
}

main();

import { describe, expect, test } from "bun:test";
import {
  validateYaml,
  checkIndentation,
  checkQuotes,
  checkBrackets,
  checkKeyValueSyntax,
  checkMultiDocument,
  type ValidationResult,
  type ValidationError,
} from "./yaml-validator";

describe("validateYaml", () => {
  describe("valid YAML cases", () => {
    test("accepts valid key-value YAML", () => {
      const yaml = `name: John
age: 30
city: New York`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("accepts valid nested YAML", () => {
      const yaml = `person:
  name: John
  address:
    city: New York
    zip: 10001`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("accepts empty content (BR-002)", () => {
      const result = validateYaml("");
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("accepts whitespace-only content (BR-002)", () => {
      const result = validateYaml("   \n  \n   ");
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("accepts comments-only content (BR-003)", () => {
      const yaml = `# This is a comment
# Another comment
   # Indented comment`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("accepts multi-document YAML (BR-004)", () => {
      const yaml = `---
name: doc1
---
name: doc2
...`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("accepts YAML with lists", () => {
      const yaml = `fruits:
  - apple
  - banana
  - orange`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("accepts YAML with inline arrays", () => {
      const yaml = `colors: [red, green, blue]`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("accepts YAML with inline objects", () => {
      const yaml = `person: {name: John, age: 30}`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("accepts YAML with quoted strings", () => {
      const yaml = `message: "Hello, World!"
note: 'Single quoted'`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });
  });

  describe("invalid YAML cases", () => {
    test("rejects unclosed double quotes", () => {
      const yaml = `name: "John`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors.some((e) => e.message.includes("Unclosed"))).toBe(true);
    });

    test("rejects unclosed single quotes", () => {
      const yaml = `name: 'John`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors.some((e) => e.message.includes("Unclosed single quote"))).toBe(true);
    });

    test("rejects tab indentation", () => {
      const yaml = "person:\n\tname: John";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors.some((e) => e.message.includes("Tab"))).toBe(true);
    });

    test("rejects inconsistent indentation", () => {
      const yaml = `person:
  name: John
   age: 30`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors.some((e) => e.message.includes("indentation"))).toBe(true);
    });

    test("rejects unclosed brackets", () => {
      const yaml = `items: [one, two`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors.some((e) => e.message.includes("Unclosed"))).toBe(true);
    });

    test("rejects unclosed braces", () => {
      const yaml = `data: {key: value`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors.some((e) => e.message.includes("Unclosed"))).toBe(true);
    });

    test("rejects invalid key-value syntax (no space after colon)", () => {
      const yaml = `name:John`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors.some((e) => e.message.includes("colon"))).toBe(true);
    });

    test("rejects mismatched brackets", () => {
      const yaml = `items: [one, two}`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors.some((e) => e.message.includes("Mismatched"))).toBe(true);
    });
  });

  describe("error details", () => {
    test("reports correct line number for unclosed quote", () => {
      const yaml = `name: John
title: "Developer
age: 30`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      const quoteError = result.errors.find((e) => e.message.includes("quote"));
      expect(quoteError).toBeDefined();
      expect(quoteError!.line).toBe(2);
    });

    test("reports correct line number for tab character", () => {
      const yaml = "line1: ok\nline2:\tvalue\nline3: fine";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      const tabError = result.errors.find((e) => e.message.includes("Tab"));
      expect(tabError).toBeDefined();
      expect(tabError!.line).toBe(2);
    });

    test("reports correct line number for bracket error", () => {
      const yaml = `list1: [a, b]
list2: [c, d
list3: [e, f]`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      const bracketError = result.errors.find((e) => e.message.includes("Unclosed"));
      expect(bracketError).toBeDefined();
      expect(bracketError!.line).toBe(2);
    });

    test("provides descriptive error message for tab", () => {
      const yaml = "key:\tvalue";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      const tabError = result.errors.find((e) => e.message.includes("Tab"));
      expect(tabError).toBeDefined();
      expect(tabError!.message).toContain("spaces");
    });

    test("provides descriptive error message for quotes", () => {
      const yaml = `msg: "hello`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      const quoteError = result.errors.find((e) => e.message.includes("quote"));
      expect(quoteError).toBeDefined();
      expect(quoteError!.message).toContain("Unclosed");
    });

    test("includes column number when available", () => {
      const yaml = "key:\tvalue";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      const tabError = result.errors.find((e) => e.message.includes("Tab"));
      expect(tabError).toBeDefined();
      expect(tabError!.column).toBeDefined();
      expect(tabError!.column).toBeGreaterThan(0);
    });
  });
});

describe("checkIndentation", () => {
  test("returns no errors for valid indentation", () => {
    const lines = ["key:", "  nested: value", "  another: value"];
    const errors = checkIndentation(lines);
    expect(errors).toHaveLength(0);
  });

  test("detects tab characters", () => {
    const lines = ["key:", "\tvalue: test"];
    const errors = checkIndentation(lines);
    expect(errors.length).toBeGreaterThan(0);
    expect(errors[0].message).toContain("Tab");
  });

  test("skips empty lines", () => {
    const lines = ["key:", "", "  nested: value"];
    const errors = checkIndentation(lines);
    expect(errors).toHaveLength(0);
  });

  test("skips comment lines", () => {
    const lines = ["# comment", "key: value"];
    const errors = checkIndentation(lines);
    expect(errors).toHaveLength(0);
  });
});

describe("checkQuotes", () => {
  test("returns no errors for balanced quotes", () => {
    const lines = ['name: "John"', "title: 'Dev'"];
    const errors = checkQuotes(lines);
    expect(errors).toHaveLength(0);
  });

  test("detects unclosed double quote", () => {
    const lines = ['name: "John'];
    const errors = checkQuotes(lines);
    expect(errors.length).toBeGreaterThan(0);
    expect(errors[0].message).toContain("double quote");
  });

  test("detects unclosed single quote", () => {
    const lines = ["name: 'John"];
    const errors = checkQuotes(lines);
    expect(errors.length).toBeGreaterThan(0);
    expect(errors[0].message).toContain("single quote");
  });

  test("handles escaped quotes correctly", () => {
    const lines = ['name: "John \\"Doe\\""'];
    const errors = checkQuotes(lines);
    expect(errors).toHaveLength(0);
  });

  test("skips comment lines", () => {
    const lines = ['# this has "unbalanced quote'];
    const errors = checkQuotes(lines);
    expect(errors).toHaveLength(0);
  });
});

describe("checkBrackets", () => {
  test("returns no errors for balanced brackets", () => {
    const lines = ["items: [a, b, c]", "data: {x: 1, y: 2}"];
    const errors = checkBrackets(lines);
    expect(errors).toHaveLength(0);
  });

  test("detects unclosed square bracket", () => {
    const lines = ["items: [a, b"];
    const errors = checkBrackets(lines);
    expect(errors.length).toBeGreaterThan(0);
    expect(errors[0].message).toContain("Unclosed");
  });

  test("detects unclosed curly brace", () => {
    const lines = ["data: {x: 1"];
    const errors = checkBrackets(lines);
    expect(errors.length).toBeGreaterThan(0);
    expect(errors[0].message).toContain("Unclosed");
  });

  test("detects mismatched brackets", () => {
    const lines = ["items: [a, b}"];
    const errors = checkBrackets(lines);
    expect(errors.length).toBeGreaterThan(0);
    expect(errors[0].message).toContain("Mismatched");
  });

  test("detects unexpected closing bracket", () => {
    const lines = ["items: a, b]"];
    const errors = checkBrackets(lines);
    expect(errors.length).toBeGreaterThan(0);
    expect(errors[0].message).toContain("Unexpected");
  });

  test("ignores brackets inside quotes", () => {
    const lines = ['message: "array: [1,2,3]"'];
    const errors = checkBrackets(lines);
    expect(errors).toHaveLength(0);
  });

  test("handles nested brackets", () => {
    const lines = ["matrix: [[1, 2], [3, 4]]"];
    const errors = checkBrackets(lines);
    expect(errors).toHaveLength(0);
  });
});

describe("checkKeyValueSyntax", () => {
  test("returns no errors for valid key-value syntax", () => {
    const lines = ["name: John", "age: 30"];
    const errors = checkKeyValueSyntax(lines);
    expect(errors).toHaveLength(0);
  });

  test("detects missing space after colon", () => {
    const lines = ["name:John"];
    const errors = checkKeyValueSyntax(lines);
    expect(errors.length).toBeGreaterThan(0);
    expect(errors[0].message).toContain("colon");
  });

  test("allows colon at end of line (block value)", () => {
    const lines = ["person:"];
    const errors = checkKeyValueSyntax(lines);
    expect(errors).toHaveLength(0);
  });

  test("allows flow sequences after colon", () => {
    const lines = ["items:[a, b, c]"];
    const errors = checkKeyValueSyntax(lines);
    expect(errors).toHaveLength(0);
  });

  test("allows flow mappings after colon", () => {
    const lines = ["data:{x: 1}"];
    const errors = checkKeyValueSyntax(lines);
    expect(errors).toHaveLength(0);
  });

  test("skips document separators", () => {
    const lines = ["---", "key: value", "..."];
    const errors = checkKeyValueSyntax(lines);
    expect(errors).toHaveLength(0);
  });

  test("skips comment lines", () => {
    const lines = ["# url:http://example.com"];
    const errors = checkKeyValueSyntax(lines);
    expect(errors).toHaveLength(0);
  });

  test("ignores colons inside quotes", () => {
    const lines = ['url: "http://example.com"'];
    const errors = checkKeyValueSyntax(lines);
    expect(errors).toHaveLength(0);
  });
});

describe("checkMultiDocument", () => {
  test("returns no errors for valid document separators", () => {
    const lines = ["---", "doc: 1", "---", "doc: 2", "..."];
    const errors = checkMultiDocument(lines);
    expect(errors).toHaveLength(0);
  });

  test("allows document separator with directive", () => {
    const lines = ["--- !custom", "doc: 1"];
    const errors = checkMultiDocument(lines);
    expect(errors).toHaveLength(0);
  });

  test("detects invalid document separator", () => {
    const lines = ["---invalid"];
    const errors = checkMultiDocument(lines);
    expect(errors.length).toBeGreaterThan(0);
    expect(errors[0].message).toContain("separator");
  });

  test("detects invalid document end marker", () => {
    const lines = ["...extra"];
    const errors = checkMultiDocument(lines);
    expect(errors.length).toBeGreaterThan(0);
    expect(errors[0].message).toContain("end marker");
  });
});

