    test("accepts YAML with inline arrays", () => {
      const yaml = `colors: [red, green, blue]`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("accepts YAML with inline objects", () => {
      const yaml = `person: {name: John, age: 30}`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("accepts YAML with quoted strings", () => {
      const yaml = `message: "Hello, World!"
note: 'Single quoted'`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });
  });

  describe("invalid YAML cases", () => {
    test("rejects unclosed double quotes", () => {
      const yaml = `name: "John`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
